class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + "安静地待着");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：喵～");
    }
}

public class Main {
    public static void main(String[] args) {
        Animal a = new Animal("大肥鱼");
        Animal b = new Cat("小橘");
        a.speak();
        b.speak();
    }
}

class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + "发出了一声叫");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    @Override
    void speak() {
        super.speak();
        System.out.println("……然后补了一声喵～");
    }
}

public class Main {
    public static void main(String[] args) {
        Cat c = new Cat("小橘");
        c.speak();
    }
}
